import {inDeployment} from './pregame.js?v=36';
import * as E from './engine.js?v=36';
import * as S from './states.js?v=36';
export const SOURCE='https://experience.corvusbelli.com/en/game-content/4fdeacaa-ad46-4d37-aa5b-d5284f452653';
export const R=20/25.4;
export const objectives=()=>[12,24,36].map((x,i)=>({id:'console'+i,name:['西','中央','东'][i]+'控制台',kind:'console',x,y:24,r:R,owner:null})).concat([0,1].map(team=>({id:'beacon'+team,name:(team?'蓝':'红')+'方信标',kind:'beacon',team,x:24,y:team?12:36,r:12.5/25.4,carrier:null})));
export const hvts=()=>[{id:'hvt0',name:'红方 HVT',owner:0,x:6,y:18,s:2,z:0},{id:'hvt1',name:'蓝方 HVT',owner:1,x:45,y:30,s:2,z:0}];
export const model=u=>!u.isDeployable&&!u.isDecoy&&S.onTable(u)&&S.active(u)&&!S.has(u,'camouflaged')&&!S.has(u,'hiddenDeployment');
export function contact(u,o){return Math.abs((u.z||0)-(o.z||0))<.01&&E.dist(u,o)<=E.radius(u)+o.r+.025;}
export const inZone=(u,p)=>p.x-E.radius(u)>=-1e-6&&p.x+E.radius(u)<=48+1e-6&&inDeployment(u,p,{attemptInfiltration:!!u.infiltrationAttempt});
export function deploymentError(u,p,units,terrain,targets=objectives()){return E.validPosition(u,p,units.filter(v=>!v.deploymentPending&&!v.offTable&&!S.has(v,'hiddenDeployment')),terrain)||(units.some(v=>v.id!==u.id&&v.team!==u.team&&!v.deploymentPending&&S.onTable(v)&&E.edgeDistance({...u,...p},v)<=.025)?'不能部署接触敌方或中立模型':'')||(!inZone(u,p)?'完整底盘超出本单位获准部署区域':'')||(u.infiltrationFailed&&Math.min(p.x-E.radius(u),48-p.x-E.radius(u),u.deploymentSide==='north'?p.y-E.radius(u):48-p.y-E.radius(u))>.025?'潜入失败：须接触己方部署区内的桌边':'')||(p.wall?'不能部署在垂直墙面':'')||(targets.some(o=>contact({...u,...p},o))?'不能部署接触任务目标':'');}
export function hvtError(h,p,terrain,others=[]){const r=E.radius(h);return (p.z||0)!==0?'HVT 必须在地面':p.x<r||p.x>48-r||p.y-r<16-1e-6||p.y+r>32+1e-6?'HVT 底盘须距任一部署区至少 4″':terrain.some(t=>E.pointRect(p,t)<r+.001)?'HVT 不能放在地形内部或顶部':others.some(v=>v.id!==h.id&&E.dist(v,p)<r+E.radius(v))?'HVT 与其他模型重叠':'';}
export function controller(o,units){const teams=new Set(units.filter(u=>model(u)&&contact(u,o)).map(u=>u.team));return teams.size===1?[...teams][0]:null;}
export function syncBeacons(state){for(const o of state.objectives.filter(o=>o.carrier)){const u=state.units.find(u=>u.id===o.carrier);if(!u)continue;o.x=E.clamp(u.x+E.radius(u)+o.r+(model(u)?0:.05),o.r,48-o.r);o.y=u.y;o.z=u.z||0;if(!model(u)){o.carrier=null;u.carryingBeacon=false;}}}
export function lockRound(state){if(state.missionId==='annihilation'||state.appMode==='tutorial'&&state.lesson!=='console')return;state.roundScores??={};if(state.roundScores[state.round])return;syncBeacons(state);state.roundScores[state.round]=[0,1].map(team=>controller(state.objectives.find(o=>o.kind==='beacon'&&o.team!==team),state.units)===team?1:0);}
export function secureHVT(state,team){const enemy=state.hvts.find(h=>h.owner!==team),own=state.hvts.find(h=>h.owner===team);return !!enemy&&!!own&&state.units.some(u=>u.team===team&&!u.isDeployable&&!u.isDecoy&&S.onTable(u)&&S.active(u)&&E.edgeDistance(u,enemy)<=8)&&!state.units.some(u=>u.team!==team&&!u.isDeployable&&!u.isDecoy&&S.onTable(u)&&S.active(u)&&E.edgeDistance(u,own)<=8);}
export function score(state){if(state.appMode==='tutorial'&&state.lesson!=='console')return [0,0];if(state.missionId==='annihilation')return annihilationScore(state);syncBeacons(state);const cs=[0,1].map(t=>state.objectives.filter(o=>o.kind==='console'&&o.owner===t).length);return [0,1].map(t=>Object.values(state.roundScores||{}).reduce((n,r)=>n+r[t],0)+cs[t]+(cs[t]>cs[1-t]?2:0)+(controller(state.objectives.find(o=>o.kind==='beacon'&&o.team===t),state.units)!==1-t?1:0)+(state.classified?.[t]?.done||state.classified?.[t]?.secure&&secureHVT(state,t)?1:0));}
export function activationSpec(u,o){return {can:!!o&&o.kind==='console'&&S.allowed(u,'attack')&&!!(u.specialist||u.forwardObserver||u.doctor||u.engineer||u.hackingDevice)&&contact(u,o),sv:u.wip||13,sd:0};}
export function activate(state,u,o,success){if(success)o.owner=u.team;}
export function pickupError(state,u,o){return !o||o.kind!=='beacon'||o.team===u.team?'只能拿取敌方信标':!model(u)?'需要非标记状态的模型':!state.objectives.some(c=>c.kind==='console'&&c.owner===u.team)?'先激活至少一个控制台':!contact(u,o)&&!(o.carrier&&E.edgeDistance(u,state.units.find(v=>v.id===o.carrier))<.025)?'需要接触信标或友方携带者':state.units.some(v=>v.team!==u.team&&model(v)&&contact(v,o))?'敌方正接触争夺信标':'';}

export const MISSIONS={hardlock:{name:'信标封锁',en:'HARDLOCK',source:SOURCE,description:'控制台、敌方信标、HVT 与机密任务。强调专家推进与目标争夺。'},annihilation:{name:'歼灭战',en:'ANNIHILATION',source:'https://experience.corvusbelli.com/en/game-content/9c6c05c2-420e-4264-8a3e-ce9704dd5c98',description:'消灭敌军、保存己方战力并击杀敌方尉官。无 HVT、机密任务或场上任务标记。'}};
export function configure(state,id='hardlock'){if(!MISSIONS[id])throw Error('不支持的ITS任务');state.missionId=id;state.objectives=id==='hardlock'?objectives():[];state.hvts=id==='hardlock'?hvts():[];state.classified=[{},{}];state.roundScores={};return state;}
const tier=n=>n>250?4:n>=151?3:n>=75?1:0;
export function annihilationValues(state){return [0,1].map(team=>{const us=state.units.filter(u=>u.team===team&&!u.peripheral&&!u.isDeployable&&!u.isDecoy);const killed=u=>S.has(u,'dead')||state.phase==='finished'&&(!S.active(u)||u.offTable||u.deploymentPending);return {killed:us.filter(killed).reduce((n,u)=>n+(u.points||0),0),surviving:us.filter(u=>!killed(u)&&S.active(u)&&!u.offTable&&!u.deploymentPending).reduce((n,u)=>n+(u.points||0),0),lieutenantKilled:us.some(u=>u.lieutenant&&killed(u))};});}
export function annihilationScore(state){const v=annihilationValues(state);return [0,1].map(t=>tier(v[1-t].killed)+tier(v[t].surviving)+(v[1-t].lieutenantKilled?2:0));}
